package com.android.tools.lint.checks;

import static com.android.SdkConstants.ANDROID_URI;
import static com.android.SdkConstants.ATTR_CLASS;
import static com.android.SdkConstants.ATTR_LAYOUT_HEIGHT;
import static com.android.SdkConstants.ATTR_LAYOUT_WIDTH;
import static com.android.SdkConstants.ATTR_STYLE;
import static com.android.SdkConstants.GRID_LAYOUT;
import static com.android.SdkConstants.VIEW_TAG;

import com.android.annotations.NonNull;
import com.android.resources.ResourceFolderType;
import com.android.tools.lint.detector.api.*;
import java.io.File;
import java.util.Collection;
import org.w3c.dom.Element;

public class RequiredAttributeDetector extends Detector implements XmlScanner {
    private static final Implementation IMPLEMENTATION = new Implementation(
            RequiredAttributeDetector.class,
            Scope.RESOURCE_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "RequiredSize",
            "Missing layout width or height",
            "...",
            Category.CORRECTNESS,
            9,
            Severity.FATAL,
            IMPLEMENTATION);

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT;
    }

    @Override
    public Collection<String> getApplicableElements() {
        return XmlScannerConstants.ALL;
    }

    @Override
    public void visitElement(XmlContext context, Element element) {
        String tag = element.getTagName();

        if (tag.isEmpty() || !isViewTag(tag)) {
            return;
        }

        if (isGridLayout(element)) {
            return;
        }

        if (element.hasAttribute(ATTR_STYLE)) {
            return;
        }

        boolean hasWidth = element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_WIDTH);
        boolean hasHeight = element.hasAttributeNS(ANDROID_URI, ATTR_LAYOUT_HEIGHT);

        if (!hasWidth && !hasHeight) {
            context.report(ISSUE, element, context.getNameLocation(element),
                    "Missing layout_width and layout_height attributes");
        } else if (!hasWidth) {
            context.report(ISSUE, element, context.getNameLocation(element),
                    "Missing layout_width attribute");
        } else if (!hasHeight) {
            context.report(ISSUE, element, context.getNameLocation(element),
                    "Missing layout_height attribute");
        }
    }

    private static boolean isViewTag(String tag) {
        return tag.contains(".") || Character.isUpperCase(tag.charAt(0)) || tag.equals(VIEW_TAG);
    }

    private static boolean isGridLayout(Element element) {
        String tag = element.getTagName();
        if (VIEW_TAG.equals(tag)) {
            String className = element.getAttribute(ATTR_CLASS);
            if (className != null && className.endsWith(GRID_LAYOUT)) {
                return true;
            }
        }
        return tag.endsWith(GRID_LAYOUT);
    }

    public static boolean hasLayoutVariations(File file) {
        String name = file.getName();
        File folder = file.getParentFile();
        if (folder == null) return false;
        File res = folder.getParentFile();
        if (res == null) return false;
        for (File sibling : res.listFiles()) {
            if (sibling.equals(folder) || !sibling.isDirectory()) continue;
            String folderName = sibling.getName();
            if (folderName.startsWith("layout")) {
                File candidate = new File(sibling, name);
                if (candidate.exists()) return true;
            }
        }
        return false;
    }
}

